s=s.replace("ledger=FeedbackLedger(n,mode);","ledger=BoundedFeedbackLedger(n) if arm=='bounded_passive' else FeedbackLedger(n,mode);")
s=s.replace("     mode={'bounded_passive'","     for sensor in range(n):lib.bridge_power_budget(sensor,.5)\n     mode={'bounded_passive'")
