s=s.replace("ledger.evidence(e.node,e.peer,pid,'passive',e.time)","ledger.evidence(e.node,e.peer,pid,'passive',now)")
s=s.replace("ledger.evidence(e.node,e.peer,pid,'receipt',e.time)","ledger.evidence(e.node,e.peer,pid,'receipt',now)")
s=s.replace("ledger.acknowledge(e.node,e.peer,pid,bool(e.ok),e.time)","ledger.acknowledge(e.node,e.peer,pid,bool(e.ok),now)")
